function initTextToolbar() {
    textToolbar = document.getElementById('textToolbar');
    document.addEventListener('selectionchange', updateToolbarPosition);

    // Prevent toolbar from closing when clicking inside it
    if (textToolbar) {
        textToolbar.addEventListener('mousedown', (e) => {
            e.preventDefault(); // Important to keep selection
        });
    }
}

function updateToolbarPosition() {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0 || selection.isCollapsed) {
        if (textToolbar) textToolbar.classList.remove('active');
        // Hide dropdowns
        document.querySelectorAll('.toolbar-dropdown-menu').forEach(el => el.classList.add('hidden'));
        return;
    }

    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    const editor = document.getElementById('notionEditor');

    // Ensure selection is inside editor OR Title
    const titleEl = document.getElementById('postTitle');
    if (!editor || (!editor.contains(selection.anchorNode) && (!titleEl || !titleEl.contains(selection.anchorNode)))) {
        if (textToolbar) textToolbar.classList.remove('active');
        return;
    }

    if (textToolbar) {
        textToolbar.style.left = (rect.left + rect.width / 2 - textToolbar.offsetWidth / 2) + 'px';
        textToolbar.style.top = (rect.top - textToolbar.offsetHeight - 10) + 'px';
        textToolbar.classList.add('active');

        // Update state of buttons (Simple check)
        // const boldBtn = document.getElementById('btnBold');
        // if (document.queryCommandState('bold')) boldBtn?.classList.add('active');
    }
}

function formatText(command, value = null) {
    if (command === 'createLink') {
        const url = prompt('Nhập đường dẫn URL:', 'https://');
        if (url) document.execCommand(command, false, url);
    } else {
        document.execCommand(command, false, value);
    }
    // Restore focus
    const selection = window.getSelection();
    if (selection.rangeCount > 0) selection.getRangeAt(0).startContainer.parentNode?.focus();
}

// Set Block Type from Toolbar
function setBlockType(type) {
    const selection = window.getSelection();
    if (!selection.rangeCount) return;

    const node = selection.anchorNode;
    const block = (node.nodeType === 3 ? node.parentNode : node).closest('.notion-block');
    if (!block) return;

    const content = block.querySelector('.notion-block-content').innerHTML;
    const newBlock = document.createElement('div');
    // ... Simplified: just replace the block content HTML/Class
    // But easier to just Add New Block and remove Old, or changing dataset.type
    // Implementation:
    const id = block.id;
    const index = Array.from(block.parentNode.children).indexOf(block);

    // We reuse addBlock logic but keep content?
    // Doing true conversion is complex. 
    // Quick fix: Remove old, Add new with same content.
    removeBlock(id);
    addBlock(type, true, index);

    // TODO: Restore content if text
    // For now simple switch
}

function toggleDropdown(id) {
    // Hide others
    document.querySelectorAll('.toolbar-dropdown-menu').forEach(e => {
        if (e.id !== id) e.classList.remove('active');
    });
    const el = document.getElementById(id);
    if (el) el.classList.toggle('active');
}

function setColor(type, color) {
    if (color === 'custom') {
        // Trigger hidden color input if exists, or prompt
        // For simple UX, let's use prompt or verify if we have input
        const customColor = prompt('Nhập mã màu (hex, rgb):', '#000000');
        if (customColor) formatText(type, customColor);
        return;
    }
    formatText(type, color);
    // Hide dropdowns
    document.querySelectorAll('.toolbar-dropdown-menu').forEach(el => el.classList.add('hidden'));
    document.querySelectorAll('.toolbar-dropdown-menu').forEach(el => el.classList.remove('active'));
}

