function createSlashMenu() {
    const menu = document.createElement('div');
    menu.id = 'slashMenu';
    menu.className = 'fixed z-50 bg-white shadow-xl rounded-lg border border-gray-200 w-80 max-h-96 overflow-y-auto py-2 animate-in fade-in zoom-in-95 duration-100';
    menu.style.display = 'none'; // Ensure hidden by default

    SLASH_MENU_ITEMS.forEach(section => {
        const title = document.createElement('div');
        title.className = 'px-3 py-1.5 text-xs font-semibold text-gray-500 uppercase tracking-wider select-none';
        title.textContent = section.title;
        menu.appendChild(title);

        section.items.forEach(item => {
            const el = document.createElement('div');
            el.className = 'flex items-center gap-3 px-3 py-2 mx-1 hover:bg-gray-100 rounded cursor-pointer transition-colors';
            el.innerHTML = `
                <div class="flex-shrink-0 w-10 h-10 flex items-center justify-center bg-white border border-gray-200 rounded shadow-sm text-gray-600">
                    <i data-lucide="${item.icon}" class="w-5 h-5"></i>
                </div>
                <div class="flex-1 min-w-0">
                    <div class="text-sm font-medium text-gray-900">${item.label}</div>
                    <div class="text-xs text-gray-400 truncate">${item.desc}</div>
                </div>
            `;
            el.onclick = (e) => {
                e.stopPropagation();
                applyBlockType(item.type);
                hideSlashMenu();
            };
            menu.appendChild(el);
        });
    });

    document.body.appendChild(menu);
    return menu;
}

function showBlockSelector(block) {
    let menu = document.getElementById('slashMenu');
    if (!menu) {
        menu = createSlashMenu();
        if (window.lucide) lucide.createIcons();
    }

    const rect = block.getBoundingClientRect();
    const menuHeight = 350; // approx
    const top = (rect.bottom + menuHeight > window.innerHeight) ? (rect.top - menuHeight) : (rect.bottom + 5);

    menu.style.top = top + 'px';
    menu.style.left = rect.left + 'px';
    menu.style.display = 'block'; // Show
    menu.classList.remove('hidden'); // Redundant but safe
    currentBlockForSelector = block;
}

function hideSlashMenu() {
    const menu = document.getElementById('slashMenu');
    if (menu) {
        menu.style.display = 'none';
        menu.classList.add('hidden');
    }
    currentBlockForSelector = null;
}

// Global Alignment Function
function setAlignment(align, targetBlock = null) {
    const selection = window.getSelection();
    let block = targetBlock;

    if (!block && selection.rangeCount > 0) {
        const node = selection.anchorNode;
        block = (node.nodeType === 3 ? node.parentNode : node).closest('.notion-block');
    }

    if (!block) return;

    // Handle Image Wrapper
    const imgWrapper = block.querySelector('.image-block-wrapper');
    if (imgWrapper) {
        imgWrapper.classList.remove('text-left', 'text-center', 'text-right');
        imgWrapper.classList.add(`text-${align}`);
        return;
    }

    // Handle Text Content
    const content = block.querySelector('.notion-block-content');
    if (content) {
        content.classList.remove('text-left', 'text-center', 'text-right');
        content.classList.add(`text-${align}`);
        content.style.textAlign = align; // Explicit style for safety logic in generateHTML
    }
}
window.setAlignment = setAlignment;

function hideSlashMenu() {
    const menu = document.getElementById('slashMenu');
    if (menu) menu.classList.add('hidden');
    currentBlockForSelector = null;
}

// Wrapper for backward compatibility or direct calls
function hideBlockSelector() {
    hideSlashMenu();
}

function showBlockMenuFor(blockId) {
    const block = document.getElementById(blockId);
    if (block) showBlockSelector(block);
}

function applyBlockType(type) {
    if (!currentBlockForSelector) return;

    const block = currentBlockForSelector;
    const editor = document.getElementById('notionEditor');
    const index = Array.from(editor.children).indexOf(block);

    // Remove old block and add new one
    removeBlock(block.id);
    addBlock(type, true, index);

    // If Image, trigger upload
    if (type === 'image') {
        setTimeout(() => {
            const uploadInput = document.getElementById('imageUpload');
            if (uploadInput) uploadInput.click();
        }, 100);
    }
}



